package com.barracudatrial.pathfinding;

import com.barracudatrial.RouteOptimization;
import lombok.Getter;
import net.runelite.api.coords.WorldPoint;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;

/**
 * Wraps a path with the danger zones that existed when it was created.
 * We need this to detect NEWLY appearing dangers - if the path already went through
 * danger zones because there was no alternative, we shouldn't rebuild it unless
 * the situation changes (new lightning clouds, new rocks, etc.)
 */
@Getter
class StabilizedPath
{
	private final PathResult pathResult;
	private final Set<WorldPoint> dangerZonesAtCreation;

	public StabilizedPath(PathResult pathResult, Set<WorldPoint> dangerZonesAtCreation)
	{
		this.pathResult = pathResult;
		this.dangerZonesAtCreation = dangerZonesAtCreation;
	}

}

/**
 * Prevents path thrashing by keeping cached paths stable when the player is following them.
 * Goals:
 * - Don't switch paths just because we moved forward (natural cost reduction)
 * - Don't switch for tiny improvements (1 tile difference)
 * - DO switch when world state changes make the old path dangerous (new lightning clouds)
 * - Treat each waypoint segment independently (don't rebuild segment 1->2 because 2->3 improved)
 */
public class PathStabilizer
{
	private final AStarPathfinder pathfinder;
	private final Map<WorldPoint, StabilizedPath> activePathsByGoal;

    public PathStabilizer(AStarPathfinder pathfinder)
	{
		this.pathfinder = pathfinder;
		this.activePathsByGoal = new HashMap<>();
	}

	public PathResult findPath(BarracudaTileCostCalculator costCalculator, RouteOptimization routeOptimization, WorldPoint start, List<PathObjective> objectives, int maxSearchDistance,
	                                  int minSpatialDistance, int boatDirectionDx, int boatDirectionDy, boolean isPlayerCurrentlyOnPath)
	{
		PathResult newPathResult = pathfinder.findPath(costCalculator, routeOptimization, start, objectives, maxSearchDistance, minSpatialDistance, boatDirectionDx, boatDirectionDy);
		Set<WorldPoint> currentDangerZones = costCalculator.getDangerZoneSnapshot();

		WorldPoint goal = objectives.get(objectives.size() - 1).getLocation();

		StabilizedPath activeStabilizedPath = activePathsByGoal.get(goal);
		PathResult activePathResult = activeStabilizedPath != null ? activeStabilizedPath.getPathResult() : null;

		if (shouldForceNewPath(activePathResult, newPathResult))
		{
			activePathsByGoal.put(goal, new StabilizedPath(newPathResult, currentDangerZones));
			return newPathResult;
		}

		if (shouldKeepActivePath(routeOptimization, start, activeStabilizedPath, newPathResult, currentDangerZones, isPlayerCurrentlyOnPath))
		{
			return getTrimmedPathResult(start, activePathResult);
		}

		activePathsByGoal.put(goal, new StabilizedPath(newPathResult, currentDangerZones));
		return newPathResult;
	}

	private boolean shouldForceNewPath(PathResult activePathResult, PathResult newPathResult)
	{
		if (activePathResult == null || activePathResult.getPath().isEmpty())
		{
			return true;
		}

		if (newPathResult.getPath().isEmpty())
		{
			return true;
		}

		if (!activePathResult.isReachedGoal() && newPathResult.isReachedGoal())
		{
			return true;
		}

		var activePathEnd = activePathResult.getPath().get(activePathResult.getPath().size() - 1);
		var newPathEnd = newPathResult.getPath().get(newPathResult.getPath().size() - 1);
        return !activePathEnd.equals(newPathEnd);
    }

	private boolean shouldKeepActivePath(RouteOptimization routeOptimization, WorldPoint start, StabilizedPath activeStabilizedPath, PathResult newPathResult, Set<WorldPoint> currentDangerZones, boolean isPlayerCurrentlyOnPath)
	{
		PathResult activePathResult = activeStabilizedPath.getPathResult();

		// If old path goes through NEW danger zones, force new path
		int closestIndex = findClosestPointOnPath(start, activePathResult.getPath());
		Set<WorldPoint> oldDangerZones = activeStabilizedPath.getDangerZonesAtCreation();
		if (doesPathIntersectNewDangerZones(activePathResult, closestIndex, oldDangerZones, currentDangerZones))
		{
			return false;
		}

		if (isPlayerCurrentlyOnPath && !isWithinProximityOfPath(start, activePathResult))
		{
			return false;
		}

        return !isNewPathSignificantlyBetter(routeOptimization, start, activePathResult, newPathResult);
    }

	private boolean isWithinProximityOfPath(WorldPoint start, PathResult pathResult)
	{
		var pathNodes = pathResult.getPathNodes();
		if (pathNodes.isEmpty())
		{
			return false;
		}

		int closestIndex = -1;
		int minDistance = Integer.MAX_VALUE;

		for (int i = 0; i < pathNodes.size(); i++)
		{
			var nodePosition = pathNodes.get(i).getPosition();
			int dx = Math.abs(start.getX() - nodePosition.getX());
			int dy = Math.abs(start.getY() - nodePosition.getY());
			int chebyshevDistance = Math.max(dx, dy);

			if (chebyshevDistance < minDistance)
			{
				minDistance = chebyshevDistance;
				closestIndex = i;
			}
		}

		// When you're at the start of a new segment (closestIndex=0), give extra leeway (5 tiles) for merging
		// onto the path. This handles waypoint pickups from a distance (~4 tiles). Once you're traveling along
		// the path (closestIndex>0), enforce stricter tolerance (3 tiles) - if you stray, recalculate.
		int tolerance = (closestIndex == 0) ? 5 : 3;

		return minDistance <= tolerance;
	}

	private boolean isNewPathSignificantlyBetter(RouteOptimization routeOptimization, WorldPoint start, PathResult activePathResult, PathResult newPathResult)
	{
		double newCost = newPathResult.getCost();

		int closestIndex = findClosestPointOnPath(start, activePathResult.getPath());
		double oldRemainingCost = activePathResult.getCostFromIndex(closestIndex);

		return newCost <= routeOptimization.getSwitchCostRatio() * oldRemainingCost;
	}

	private boolean doesPathIntersectNewDangerZones(PathResult pathResult, int fromIndex, Set<WorldPoint> oldDangerZones, Set<WorldPoint> currentDangerZones)
	{
		// Find danger zones that exist now but didn't exist when the path was created
		Set<WorldPoint> newDangerZones = new HashSet<>(currentDangerZones);
		newDangerZones.removeAll(oldDangerZones);

		// Check if path intersects any of these NEW danger zones
		List<PathNode> pathNodes = pathResult.getPathNodes();
		for (int i = fromIndex; i < pathNodes.size(); i++)
		{
			if (newDangerZones.contains(pathNodes.get(i).getPosition()))
			{
				return true;
			}
		}
		return false;
	}

	private PathResult getTrimmedPathResult(WorldPoint start, PathResult pathResult)
	{
		List<PathNode> fullPathNodes = pathResult.getPathNodes();
		List<WorldPoint> fullPath = pathResult.getPath();
		int closestIndex = findClosestPointOnPath(start, fullPath);

		// If player is exactly on the closest path tile, start from next tile
		if (closestIndex < fullPath.size() && fullPath.get(closestIndex).equals(start))
		{
			closestIndex++;
		}

		// Return remaining path from that point forward
		if (closestIndex >= fullPathNodes.size())
		{
			return new PathResult(new ArrayList<>(), Double.POSITIVE_INFINITY, pathResult.isReachedGoal());
		}

		List<PathNode> trimmedNodes = new ArrayList<>(fullPathNodes.subList(closestIndex, fullPathNodes.size()));
		double trimmedCost = pathResult.getCostFromIndex(closestIndex);
		return new PathResult(trimmedNodes, trimmedCost, pathResult.isReachedGoal());
	}

	private int findClosestPointOnPath(WorldPoint position, List<WorldPoint> path)
	{
		int closestIndex = 0;
		double minDistance = Double.POSITIVE_INFINITY;

		for (int i = 0; i < path.size(); i++)
		{
			int dx = position.getX() - path.get(i).getX();
			int dy = position.getY() - path.get(i).getY();
			double distance = Math.sqrt(dx * dx + dy * dy);

			if (distance < minDistance)
			{
				minDistance = distance;
				closestIndex = i;
			}
		}

		return closestIndex;
	}

	public void clearActivePath()
	{
		this.activePathsByGoal.clear();
	}
}

package com.barracudatrial.pathfinding;

import com.barracudatrial.RouteOptimization;
import net.runelite.api.coords.WorldPoint;

import lombok.extern.slf4j.Slf4j;

import java.util.*;

/**
 * A* pathfinding algorithm for finding optimal routes between points
 * considering variable tile costs (speed boosts, clouds, rocks, etc.)
 */
@Slf4j
public class AStarPathfinder
{
	private static final long TIMEOUT_MS = 3000;
	private static final long TIMEOUT_NANOS = TIMEOUT_MS * 1_000_000L;

	private static final int[] HEADING_DELTAS = {-1, 0, 1};

	public PathResult findPath(BarracudaTileCostCalculator costCalculator, RouteOptimization routeOptimization, WorldPoint start, List<PathObjective> objectives, int maxSearchDistance, int minSpatialDistance, int boatDirectionDx, int boatDirectionDy)
	{
		if (objectives.isEmpty())
		{
			return new PathResult(new ArrayList<>(), Double.POSITIVE_INFINITY, false);
		}

		Search search = new Search(costCalculator, routeOptimization, start, objectives, maxSearchDistance, minSpatialDistance, boatDirectionDx, boatDirectionDy);
		return search.run();
	}

	private static final class Search
	{
		private final BarracudaTileCostCalculator costCalculator;
		private final RouteOptimization routeOptimization;
		private final WorldPoint start;
		private final List<PathObjective> objectives;
		private final int maxSearchDistance;
		private final int minSpatialDistance;
		private final int boatDirectionDx;
		private final int boatDirectionDy;

		private final PriorityQueue<Node> openSet = new PriorityQueue<>(
			Comparator.comparingDouble((Node n) -> n.fScore)
		);
		private final Map<StateKey, Node> allNodes = new HashMap<>();
		private final Set<StateKey> closedSet = new HashSet<>();

		Search(BarracudaTileCostCalculator costCalculator, RouteOptimization routeOptimization, WorldPoint start, List<PathObjective> objectives, int maxSearchDistance, int minSpatialDistance, int boatDirectionDx, int boatDirectionDy)
		{
			this.costCalculator = costCalculator;
			this.routeOptimization = routeOptimization;
			this.start = start;
			this.objectives = objectives;
			this.maxSearchDistance = maxSearchDistance;
			this.minSpatialDistance = minSpatialDistance;
			this.boatDirectionDx = boatDirectionDx;
			this.boatDirectionDy = boatDirectionDy;
		}

		PathResult run()
		{
			long startTime = System.nanoTime();

			Node startNode = new Node(start);
			startNode.gScore = 0;
			startNode.hScore = heuristic(start);
			startNode.fScore = startNode.hScore;
			startNode.headingIdx = initialHeadingIndex();
			startNode.objectiveIndex = advanceObjectiveIndex(start, 0);

			if (hasClearedAllObjectives(startNode))
			{
				return new PathResult(reconstructPath(startNode), 0, true);
			}

			openSet.add(startNode);
			allNodes.put(stateKeyOf(startNode), startNode);

			int nodesExplored = 0;
			Node bestNodeSoFar = startNode;
			int bestObjectiveIndex = startNode.objectiveIndex;
			int bestDistanceToObjective = Integer.MAX_VALUE;
			int maxSpatialDistanceReached = 0;

			while (!openSet.isEmpty())
			{
				Node current = openSet.poll();

				StateKey currentKey = stateKeyOf(current);
				if (closedSet.contains(currentKey))
				{
					continue;
				}

				if (hasClearedAllObjectives(current))
				{
					return new PathResult(reconstructPath(current), current.gScore, true);
				}

				int distanceToObjective = chebyshevDistance(current.position, objectives.get(current.objectiveIndex).getLocation());
				boolean madeProgress = current.objectiveIndex > bestObjectiveIndex
					|| (current.objectiveIndex == bestObjectiveIndex && distanceToObjective < bestDistanceToObjective);

				if (madeProgress)
				{
					bestObjectiveIndex = current.objectiveIndex;
					bestDistanceToObjective = distanceToObjective;
					bestNodeSoFar = current;
				}

				closedSet.add(currentKey);
				nodesExplored++;

				maxSpatialDistanceReached = Math.max(maxSpatialDistanceReached, chebyshevDistance(current.position, start));

				// Ensure we search minimum distance forward even when obstacles consume node budget
				if (nodesExplored > maxSearchDistance * maxSearchDistance && maxSpatialDistanceReached >= minSpatialDistance)
				{
					break;
				}

				if ((nodesExplored & 0xFF) == 0 && (System.nanoTime() - startTime) > TIMEOUT_NANOS)
				{
					log.warn("Pathfinding timeout after {}ms ({} nodes explored, cleared {} of {} objectives, best distance to next: {})",
						TIMEOUT_MS, nodesExplored, bestObjectiveIndex, objectives.size(), bestDistanceToObjective);
					break;
				}

				expandNeighborsOf(current);
			}

			// If we failed to clear every objective, return the furthest progress we found
			if (bestNodeSoFar != startNode)
			{
				return new PathResult(reconstructPath(bestNodeSoFar), bestNodeSoFar.gScore, false);
			}

			return new PathResult(new ArrayList<>(), Double.POSITIVE_INFINITY, false);
		}

		private boolean hasClearedAllObjectives(Node node)
		{
			return node.objectiveIndex >= objectives.size();
		}

		private int advanceObjectiveIndex(WorldPoint position, int objectiveIndex)
		{
			int index = objectiveIndex;

			while (index < objectives.size() && objectives.get(index).isSatisfiedAt(position))
			{
				index++;
			}

			return index;
		}

		// Steering neighbors: delta heading -1,0,+1 (±15°) and move one tile in the heading's dominant 8-way direction
		private void expandNeighborsOf(Node current)
		{
			// If unknown heading, treat each 8-way direction as a possible base heading
			if (current.headingIdx == -1)
			{
				for (int baseDir8 = 0; baseDir8 < 8; baseDir8++)
				{
					relaxNeighbor(current, DIR8_TO_HEADING24[baseDir8], 0);
				}

				return;
			}

			for (int deltaH : HEADING_DELTAS)
			{
				relaxNeighbor(current, (current.headingIdx + deltaH + 24) % 24, Math.abs(deltaH));
			}
		}

		private void relaxNeighbor(Node current, int nextHeading, int headingDelta)
		{
			int moveDir = headingToDir8(nextHeading);
			int dx = DIRS[moveDir][0];
			int dy = DIRS[moveDir][1];
			WorldPoint neighbor = new WorldPoint(current.position.getX() + dx, current.position.getY() + dy, current.position.getPlane());

			int neighborObjectiveIndex = advanceObjectiveIndex(neighbor, current.objectiveIndex);
			StateKey neighborKey = new StateKey(neighbor, nextHeading, neighborObjectiveIndex);
			if (closedSet.contains(neighborKey))
			{
				return;
			}

			double tileCost = costCalculator.getTileCost(current.position, neighbor, current.objectiveIndex);
			if (tileCost > 50000)
			{
				return;
			}

			boolean isDiagonal = dx != 0 && dy != 0;
			double geometricDistance = isDiagonal ? Math.sqrt(2) : 1.0;
			double turningCost = calculateTurningCost(routeOptimization, headingDelta);

			double tentativeGScore = current.gScore + (tileCost * geometricDistance) + turningCost;

			Node neighborNode = allNodes.get(neighborKey);
			if (neighborNode == null)
			{
				neighborNode = new Node(neighbor);
				neighborNode.headingIdx = nextHeading;
				neighborNode.objectiveIndex = neighborObjectiveIndex;
				allNodes.put(neighborKey, neighborNode);
			}

			if (tentativeGScore < neighborNode.gScore)
			{
				neighborNode.parent = current;
				neighborNode.gScore = tentativeGScore;
				neighborNode.hScore = heuristic(neighbor);
				neighborNode.fScore = neighborNode.gScore + neighborNode.hScore;

				openSet.add(neighborNode);
			}
		}

		// Map the provided 8-way boat direction into a 24-heading index (15° steps)
		private int initialHeadingIndex()
		{
			if (boatDirectionDx == 0 && boatDirectionDy == 0)
			{
				return -1;
			}

			int baseDir8 = dirIndex(Integer.signum(boatDirectionDx), Integer.signum(boatDirectionDy));
			return baseDir8 == -1 ? -1 : DIR8_TO_HEADING24[baseDir8];
		}

		private StateKey stateKeyOf(Node node)
		{
			return new StateKey(node.position, node.headingIdx, node.objectiveIndex);
		}

		/**
		 * Heuristic: returns 0 (Dijkstra mode).
		 * Rationale: tile costs may be negative (speed boosts), so admissible heuristics like
		 * Manhattan/Chebyshev are not safe; Dijkstra guarantees optimality.
		 */
		private double heuristic(WorldPoint from)
		{
			return 0;
		}
	}

	private static double calculateTurningCost(RouteOptimization routeOptimization, int absDelta)
	{
		// absDelta is the absolute heading step change (in 24-heading units: 0 or 1 here)
		if (absDelta == 0)
		{
			return 0.0;
		}

		var angle = absDelta * 15;
		var baseCost = routeOptimization.getTurnPenaltyBase();

		return angle > 105 ? baseCost * 4 : baseCost;
	}

	private static int chebyshevDistance(WorldPoint from, WorldPoint to)
	{
		return Math.max(Math.abs(from.getX() - to.getX()), Math.abs(from.getY() - to.getY()));
	}

	private static int dirIndex(int dx, int dy)
	{
		for (int i = 0; i < DIRS.length; i++)
		{
			if (DIRS[i][0] == dx && DIRS[i][1] == dy)
			{
				return i;
			}
		}
		return -1;
	}

	// Map 24 headings (15° each) to the dominant 8-way movement direction
	private static final int[] HEADING_TO_DIR8 = {
		0, 0,    // 0°, 15° -> E
		1, 1, 1, // 30°,45°,60° -> NE
		2, 2, 2, // 75°,90°,105° -> N
		3, 3, 3, // 120°,135°,150° -> NW
		4, 4, 4, // 165°,180°,195° -> W
		5, 5, 5, // 210°,225°,240° -> SW
		6, 6, 6, // 255°,270°,285° -> S
		7, 7, 7, // 300°,315°,330° -> SE
		0        // 345° -> E
	};

	private static final int[] DIR8_TO_HEADING24 = {0, 2, 5, 8, 12, 15, 18, 21};

	private static int headingToDir8(int headingIdx)
	{
		int idx = (headingIdx % 24 + 24) % 24;
		return HEADING_TO_DIR8[idx];
	}

	private static List<PathNode> reconstructPath(Node goalNode)
	{
		List<PathNode> pathNodes = new ArrayList<>();
		Node current = goalNode;

		while (current != null)
		{
			pathNodes.add(new PathNode(current.position, current.gScore));
			current = current.parent;
		}

		// Reverse to get path from start to goal
		Collections.reverse(pathNodes);
		return pathNodes;
	}

	private static final int[][] DIRS = {
		{1, 0},   // 0: E
		{1, 1},   // 1: NE
		{0, 1},   // 2: N
		{-1, 1},  // 3: NW
		{-1, 0},  // 4: W
		{-1, -1}, // 5: SW
		{0, -1},  // 6: S
		{1, -1}   // 7: SE
	};

	private static final class StateKey
	{
		private final WorldPoint pos;
		private final int headingIdx;
		private final int objectiveIndex;

		StateKey(WorldPoint pos, int headingIdx, int objectiveIndex)
		{
			this.pos = pos;
			this.headingIdx = headingIdx;
			this.objectiveIndex = objectiveIndex;
		}

		@Override
		public boolean equals(Object o)
		{
			if (this == o) return true;
			if (o == null || getClass() != o.getClass()) return false;
			StateKey stateKey = (StateKey) o;
			return headingIdx == stateKey.headingIdx && objectiveIndex == stateKey.objectiveIndex && pos.equals(stateKey.pos);
		}

		@Override
		public int hashCode()
		{
			return Objects.hash(pos, headingIdx, objectiveIndex);
		}
	}

	private static class Node
	{
		WorldPoint position;
		Node parent;
		int headingIdx = -1; // 0..23 or -1 for unknown
		int objectiveIndex = 0; // how many ordered objectives this node has already cleared
		double gScore = Double.POSITIVE_INFINITY; // Cost from start to this node
		double hScore = 0; // Heuristic cost from this node to goal
		double fScore = Double.POSITIVE_INFINITY; // Total cost (g + h)

		Node(WorldPoint position)
		{
			this.position = position;
		}
	}
}

package com.barracudatrial.pathfinding;

import lombok.Getter;
import net.runelite.api.coords.WorldPoint;

import java.util.Collections;
import java.util.HashSet;
import java.util.Set;

@Getter
public class PathObjective
{
	private final WorldPoint location;
	private final int toleranceTiles;
	private final Set<WorldPoint> approachHints;

	public PathObjective(WorldPoint location, int toleranceTiles)
	{
		this(location, toleranceTiles, null);
	}

	public PathObjective(WorldPoint location, int toleranceTiles, Set<WorldPoint> approachHints)
	{
		this.location = location;
		this.toleranceTiles = toleranceTiles;
		this.approachHints = approachHints == null || approachHints.isEmpty()
			? Collections.emptySet()
			: new HashSet<>(approachHints);
	}

	public boolean isSatisfiedAt(WorldPoint position)
	{
		int dx = Math.abs(position.getX() - location.getX());
		int dy = Math.abs(position.getY() - location.getY());
		return Math.max(dx, dy) <= toleranceTiles;
	}

	@Override
	public String toString()
	{
		return String.format("%s within %d", location, toleranceTiles);
	}
}

package com.barracudatrial.pathfinding;

import com.barracudatrial.RouteOptimization;
import net.runelite.api.coords.WorldPoint;

import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;

public class BarracudaTileCostCalculator
{
	private static final int DISCOURAGED_TILE_COST = 100;
	private static final int NEARBY_TILE_COST = 3;

	private final RouteOptimization routeOptimization;
	private final List<PathObjective> objectives;

	private int speedBoostTilesRemaining = 0;
	private WorldPoint lastTile = null;
	private boolean wasOnHintLastTile = false;
	private final Set<WorldPoint> consumedBoosts = new HashSet<>();

	private final Set<WorldPoint> discouragedTiles;
	private final Set<WorldPoint> nearDiscouragedTiles;
	private final Set<WorldPoint> cloudDangerZones;
	private final Set<WorldPoint> harmlessFetidPoolTiles;
	private final Map<WorldPoint, List<WorldPoint>> boostGrabbableTiles;

	public BarracudaTileCostCalculator(
		Map<WorldPoint, List<WorldPoint>> knownSpeedBoostLocations,
		Set<WorldPoint> knownRockLocations,
		Set<WorldPoint> knownFetidPoolLocations,
		Set<WorldPoint> knownToadPillarLocations,
		Set<WorldPoint> cloudLocations,
		int exclusionZoneMinX,
		int exclusionZoneMaxX,
		int exclusionZoneMinY,
		int exclusionZoneMaxY,
		WorldPoint primaryObjectiveLocation,
		WorldPoint secondaryObjectiveLocation,
		RouteOptimization routeOptimization,
		int boatExclusionWidth,
		int boatExclusionHeight,
		List<PathObjective> objectives,
		Set<WorldPoint> knownLandTiles,
		WorldPoint boatLocation,
		int fetidPoolImmuneTileRange)
	{
		this.routeOptimization = routeOptimization;
		this.objectives = objectives != null ? objectives : List.of();
		this.boostGrabbableTiles = knownSpeedBoostLocations;

		this.cloudDangerZones = precomputeCloudDangerZones(cloudLocations);

		this.discouragedTiles = new HashSet<>();
		discouragedTiles.addAll(knownLandTiles);
		discouragedTiles.addAll(knownRockLocations);
		discouragedTiles.addAll(knownFetidPoolLocations);
		discouragedTiles.addAll(knownToadPillarLocations);
		discouragedTiles.addAll(cloudDangerZones);
		addExclusionZoneTiles(discouragedTiles, exclusionZoneMinX, exclusionZoneMaxX, exclusionZoneMinY, exclusionZoneMaxY);
		addBoatExclusionZoneTiles(discouragedTiles, primaryObjectiveLocation, boatExclusionWidth, boatExclusionHeight);
		addBoatExclusionZoneTiles(discouragedTiles, secondaryObjectiveLocation, boatExclusionWidth, boatExclusionHeight);

		Set<WorldPoint> discouragedTilesOtherThanFetidPools = new HashSet<>(discouragedTiles);
		discouragedTilesOtherThanFetidPools.removeAll(knownFetidPoolLocations);

		this.harmlessFetidPoolTiles = precomputeHarmlessFetidPoolTiles(
			knownFetidPoolLocations, discouragedTilesOtherThanFetidPools, boatLocation, fetidPoolImmuneTileRange);

		Set<WorldPoint> stillHarmfulTiles = new HashSet<>(discouragedTiles);
		stillHarmfulTiles.removeAll(harmlessFetidPoolTiles);

		this.nearDiscouragedTiles = precomputeTileProximity(stillHarmfulTiles, 1);
	}

	private static Set<WorldPoint> precomputeHarmlessFetidPoolTiles(
		Set<WorldPoint> fetidPoolLocations,
		Set<WorldPoint> discouragedTilesOtherThanFetidPools,
		WorldPoint boatLocation,
		int immuneTileRange)
	{
		if (boatLocation == null || immuneTileRange <= 0)
		{
			return Collections.emptySet();
		}

		Set<WorldPoint> harmlessTiles = new HashSet<>();

		for (WorldPoint pool : fetidPoolLocations)
		{
			if (discouragedTilesOtherThanFetidPools.contains(pool))
			{
				continue;
			}

			int distance = Math.max(
				Math.abs(pool.getX() - boatLocation.getX()),
				Math.abs(pool.getY() - boatLocation.getY())
			);

			if (distance <= immuneTileRange)
			{
				harmlessTiles.add(pool);
			}
		}

		return harmlessTiles;
	}

	public double getTileCost(WorldPoint from, WorldPoint to, int objectiveIndex)
	{
		boolean isHintTile = isApproachHintFor(to, objectiveIndex);

		if (lastTile == null || !lastTile.equals(from))
		{
			speedBoostTilesRemaining = 0;
			wasOnHintLastTile = false;
		}

		if (isHintTile)
		{
			lastTile = to;
			wasOnHintLastTile = true;
			return -10.0;
		}

		lastTile = to;

		double cost = 1.0;

		if (wasOnHintLastTile)
		{
			cost *= 0.75;
		}

		wasOnHintLastTile = false;

		WorldPoint unconsumedBoost = getUnconsumedBoost(to);
		if (unconsumedBoost != null)
		{
			cost = routeOptimization.getSpeedBoostCost();
			speedBoostTilesRemaining = 15;
			consumedBoosts.add(unconsumedBoost);
		}
		else if (speedBoostTilesRemaining > 0)
		{
			cost /= 2.0; // Double speed
			speedBoostTilesRemaining--;
		}

		if (discouragedTiles.contains(to) && !harmlessFetidPoolTiles.contains(to))
		{
			cost += DISCOURAGED_TILE_COST;
			// Lightning clouds cancel any active speed boost
			if (cloudDangerZones.contains(to))
			{
				speedBoostTilesRemaining = 0;
			}
		}
		else if (nearDiscouragedTiles.contains(to))
		{
			cost += NEARBY_TILE_COST;
		}

		return cost;
	}

	private boolean isApproachHintFor(WorldPoint tile, int objectiveIndex)
	{
		if (objectiveIndex < 0 || objectiveIndex >= objectives.size())
		{
			return false;
		}

		return objectives.get(objectiveIndex).getApproachHints().contains(tile);
	}

	private WorldPoint getUnconsumedBoost(WorldPoint tile)
	{
		List<WorldPoint> boosts = boostGrabbableTiles.get(tile);
		if (boosts != null && boosts.contains(tile) && !consumedBoosts.contains(tile))
		{
			return tile;
		}
		return null;
	}

	/**
	 * Get a snapshot of all current discouraged tiles for path stability tracking
	 */
	public Set<WorldPoint> getDangerZoneSnapshot()
	{
		return new HashSet<>(discouragedTiles);
	}

	private static void addExclusionZoneTiles(Set<WorldPoint> tiles, int minX, int maxX, int minY, int maxY)
	{
		if (minX == 0 && maxX == 0 && minY == 0 && maxY == 0)
		{
			return;
		}

		for (int x = minX; x <= maxX; x++)
		{
			for (int y = minY; y <= maxY; y++)
			{
				tiles.add(new WorldPoint(x, y, 0));
			}
		}
	}

	// Discourage tiles around objectives so the pathfinder doesn't try to cut through the boat
	private static void addBoatExclusionZoneTiles(Set<WorldPoint> tiles, WorldPoint center, int width, int height)
	{
		if (center == null)
		{
			return;
		}

		int halfWidth = width / 2;
		int halfHeight = height / 2;

		for (int x = center.getX() - halfWidth; x <= center.getX() + halfWidth; x++)
		{
			for (int y = center.getY() - halfHeight; y <= center.getY() + halfHeight; y++)
			{
				tiles.add(new WorldPoint(x, y, center.getPlane()));
			}
		}
	}

	private Set<WorldPoint> precomputeTileProximity(Set<WorldPoint> locations, int maxDistance)
	{
		Set<WorldPoint> proximityTiles = new HashSet<>();
		int maxDistSq = maxDistance * maxDistance;

		for (WorldPoint location : locations)
		{
			int baseX = location.getX();
			int baseY = location.getY();
			int plane = location.getPlane();

			for (int dx = -maxDistance; dx <= maxDistance; dx++)
			{
				int dxSq = dx * dx;

				for (int dy = -maxDistance; dy <= maxDistance; dy++)
				{
					if (dx == 0 && dy == 0)
					{
						continue; // skip the location tile itself
					}

					int distSq = dxSq + dy * dy;
					if (distSq > maxDistSq)
					{
						continue;
					}

					WorldPoint tile = new WorldPoint(baseX + dx, baseY + dy, plane);

					// Don't consider tiles that are themselves location tiles
					if (!locations.contains(tile))
					{
						proximityTiles.add(tile);
					}
				}
			}
		}

		return proximityTiles;
	}

	/**
	 * Precomputes all tiles within cloud danger zones for O(1) lookup
	 */
	private Set<WorldPoint> precomputeCloudDangerZones(Set<WorldPoint> cloudLocations)
	{
		Set<WorldPoint> dangerZones = new HashSet<>();

		for (WorldPoint cloudLoc : cloudLocations)
		{
			int plane = cloudLoc.getPlane();

			// Add all tiles within distance 3 of cloud
			for (int dx = -3; dx <= 3; dx++)
			{
				for (int dy = -3; dy <= 3; dy++)
				{
					WorldPoint tile = new WorldPoint(cloudLoc.getX() + dx, cloudLoc.getY() + dy, plane);
					double dist = Math.sqrt(dx * dx + dy * dy);
					if (dist <= 3)
					{
						dangerZones.add(tile);
					}
				}
			}
		}

		return dangerZones;
	}
}

