	 */
	public void resetAllTemporaryState()
	{
		currentTrial = null;
		inTrial = false;
		lightningClouds.clear();
		dangerousClouds.clear();
		knownToadPillars.clear();
		rumPickupLocation = null;
		rumReturnLocation = null;
		rumsCollected = 0;
		lostSuppliesCollected = 0;
		lostSuppliesTotal = 0;
		hasThrowableObjective = false;
		boatLocation = null;
		currentLap = 1;
