	public void discardLearnedTerrainIfTrialTypeChanged(TrialType trialType)
	{
		if (learnedTerrainTrialType == trialType)
		{
			return;
		}

		clearLearnedTerrain();
		learnedTerrainTrialType = trialType;
	}

	public void clearLearnedTerrain()
